import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, ActivatedRoute } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../../core/services/api.service';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-destination-detail',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div *ngIf="destination" class="fade-in">
      <div class="detail-hero">
        <img [src]="destination.images[0]?.url || 'https://picsum.photos/seed/' + destination.slug + '/1200/600'" [alt]="destination.name">
        <div class="detail-hero-overlay">
          <div class="container">
            <div class="breadcrumb">
              <a routerLink="/">Trang chủ</a>
              <span class="material-icons">chevron_right</span>
              <a routerLink="/destinations">Điểm đến</a>
              <span class="material-icons">chevron_right</span>
              <span>{{ destination.name }}</span>
            </div>
            <h1>{{ destination.name }}</h1>
            <p><span class="material-icons">location_on</span> {{ destination.address }}</p>
            <div class="detail-meta">
              <span class="badge badge-warning" *ngIf="destination.isFeatured">Nổi bật</span>
              <span class="badge badge-primary">{{ destination.category?.name }}</span>
              <span class="rating">
                <span class="score">{{ destination.rating }}</span>
                <span class="stars">★★★★★</span>
                <span>({{ destination.reviewCount }} đánh giá)</span>
              </span>
            </div>
          </div>
        </div>
      </div>

      <section class="section">
        <div class="container">
          <div class="detail-layout">
            <div class="detail-main">
              <!-- Gallery -->
              <div class="gallery" *ngIf="destination.images?.length">
                <div class="gallery-grid">
                  <img *ngFor="let img of destination.images.slice(0,4)" [src]="img.url" [alt]="img.caption">
                </div>
              </div>

              <!-- Description -->
              <div class="content-section">
                <h2>Giới thiệu</h2>
                <div class="content" [innerHTML]="destination.description"></div>
              </div>

              <!-- Info Cards -->
              <div class="info-cards grid grid-3">
                <div class="info-card">
                  <span class="material-icons">schedule</span>
                  <h4>Thời gian đẹp nhất</h4>
                  <p>{{ destination.bestTime }}</p>
                </div>
                <div class="info-card">
                  <span class="material-icons">attach_money</span>
                  <h4>Chi phí ước tính</h4>
                  <p>{{ destination.estimatedCost }}</p>
                </div>
                <div class="info-card">
                  <span class="material-icons">visibility</span>
                  <h4>Lượt xem</h4>
                  <p>{{ destination.viewCount }}</p>
                </div>
              </div>

              <!-- Highlights -->
              <div class="content-section" *ngIf="destination.highlights">
                <h2>Điểm nổi bật</h2>
                <div class="highlights-list">
                  <div *ngFor="let h of getHighlights()" class="highlight-item">
                    <span class="material-icons">check_circle</span>
                    {{ h }}
                  </div>
                </div>
              </div>

              <!-- Tips -->
              <div class="content-section" *ngIf="destination.tips">
                <h2>Mẹo du lịch</h2>
                <p>{{ destination.tips }}</p>
              </div>

              <!-- Reviews -->
              <div class="content-section">
                <h2>Đánh giá ({{ destination.reviewCount }})</h2>

                <!-- Write Review -->
                <div class="write-review" *ngIf="auth.isLoggedIn()">
                  <h4>Viết đánh giá của bạn</h4>
                  <div class="rating-input">
                    <span *ngFor="let s of [1,2,3,4,5]" class="star" [class.filled]="s <= newReview.rating" (click)="newReview.rating = s">
                      <span class="material-icons">{{ s <= newReview.rating ? 'star' : 'star_border' }}</span>
                    </span>
                  </div>
                  <textarea class="form-control" [(ngModel)]="newReview.comment" placeholder="Chia sẻ trải nghiệm của bạn..." rows="3"></textarea>
                  <button class="btn btn-primary" (click)="submitReview()" [disabled]="!newReview.rating || !newReview.comment.trim()">
                    Gửi đánh giá
                  </button>
                  <p class="success-msg" *ngIf="reviewSuccess">Đánh giá đã được gửi!</p>
                </div>
                <div class="login-prompt" *ngIf="!auth.isLoggedIn()">
                  <p>Hãy <a routerLink="/auth/login">đăng nhập</a> để viết đánh giá.</p>
                </div>

                <!-- Review List -->
                <div class="reviews-list">
                  <div *ngFor="let r of reviews" class="review-item">
                    <div class="review-avatar">
                      <span class="material-icons">person</span>
                    </div>
                    <div class="review-content">
                      <div class="review-header">
                        <strong>{{ r.user?.fullName }}</strong>
                        <div class="review-rating">
                          <span *ngFor="let s of [1,2,3,4,5]" class="material-icons" [class.filled]="s <= r.rating">star</span>
                        </div>
                      </div>
                      <p>{{ r.comment }}</p>
                      <span class="review-date">{{ r.createdAt | date:'dd/MM/yyyy' }}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div class="detail-sidebar">
              <!-- Action Card -->
              <div class="action-card card">
                <div class="card-body">
                  <button class="btn btn-primary btn-lg" style="width:100%;" (click)="toggleFavorite()">
                    <span class="material-icons">{{ isFavorite ? 'favorite' : 'favorite_border' }}</span>
                    {{ isFavorite ? 'Đã yêu thích' : 'Thêm vào yêu thích' }}
                  </button>
                  <button class="btn btn-accent btn-lg" style="width:100%;margin-top:0.75rem;" routerLink="/contact">
                    <span class="material-icons">support_agent</span>
                    Yêu cầu tư vấn
                  </button>
                </div>
              </div>

              <!-- Related -->
              <div class="related-section" *ngIf="relatedDestinations.length">
                <h3>Địa điểm liên quan</h3>
                <div *ngFor="let r of relatedDestinations" class="related-item">
                  <img [src]="r.images[0]?.url || 'https://picsum.photos/seed/' + r.slug + '/100/100'" [alt]="r.name">
                  <div>
                    <a [routerLink]="['/destinations', r.slug]">{{ r.name }}</a>
                    <p>{{ r.province?.name }}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>

    <div class="loading-spinner" *ngIf="!destination && !loadingError">
      <div class="spinner"></div>
    </div>

    <div class="empty-state" *ngIf="loadingError">
      <span class="material-icons">error_outline</span>
      <h3>Không tìm thấy địa điểm</h3>
      <a routerLink="/destinations" class="btn btn-primary">Quay lại danh sách</a>
    </div>
  `,
  styles: [`
    .breadcrumb {
      display: flex;
      align-items: center;
      gap: 0.25rem;
      font-size: 0.875rem;
      margin-bottom: 0.5rem;
      a { color: rgba(255,255,255,0.8); &:hover { color: white; } }
      .material-icons { font-size: 1rem; }
      span { color: rgba(255,255,255,0.6); }
    }
    .detail-meta { display: flex; align-items: center; gap: 0.75rem; margin-top: 0.5rem; flex-wrap: wrap; }

    .detail-layout { display: grid; grid-template-columns: 1fr 320px; gap: 2rem; @media(max-width:768px){grid-template-columns:1fr;} }
    .gallery-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 0.5rem; margin-bottom: 2rem; img { width:100%; height:200px; object-fit:cover; border-radius:8px; } }

    .content-section { margin-bottom: 2rem; h2 { font-size: 1.5rem; margin-bottom: 1rem; padding-bottom: 0.5rem; border-bottom: 2px solid #e2e8f0; } }
    .content { line-height: 1.8; color: var(--gray-dark); p { margin-bottom: 1rem; } }

    .info-cards { gap: 1rem; }
    .info-card {
      background: var(--light);
      border-radius: var(--border-radius-sm);
      padding: 1.25rem;
      text-align: center;
      .material-icons { font-size: 1.5rem; color: var(--primary); margin-bottom: 0.5rem; }
      h4 { font-size: 0.875rem; color: var(--gray); margin-bottom: 0.25rem; }
      p { font-weight: 600; margin: 0; }
    }

    .highlights-list { display: grid; grid-template-columns: repeat(2,1fr); gap: 0.75rem; }
    .highlight-item { display: flex; align-items: center; gap: 0.5rem; .material-icons { color: var(--secondary); font-size: 1.125rem; } }

    .write-review { background: var(--light); border-radius: var(--border-radius); padding: 1.5rem; margin-bottom: 2rem; }
    .rating-input { display: flex; gap: 0.25rem; margin: 0.75rem 0; cursor: pointer; }
    .star .material-icons { font-size: 2rem; color: #ddd; transition: color 0.2s; }
    .star.filled .material-icons, .star .material-icons.filled { color: #f59e0b; }
    .rating-input .material-icons { font-size: 2rem; color: #ddd; }
    .rating-input .filled { color: #f59e0b !important; }

    .success-msg { color: var(--secondary); font-weight: 600; margin: 0.5rem 0 0; }

    .login-prompt { background: var(--light); border-radius: var(--border-radius); padding: 1.5rem; text-align: center; margin-bottom: 2rem; }

    .reviews-list { display: flex; flex-direction: column; gap: 1.5rem; }
    .review-item { display: flex; gap: 1rem; padding: 1.25rem; background: var(--light); border-radius: var(--border-radius-sm); }
    .review-avatar { width: 48px; height: 48px; border-radius: 50%; background: var(--primary); color: white; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .review-header { display: flex; align-items: center; gap: 0.75rem; margin-bottom: 0.25rem; }
    .review-rating { display: flex; .material-icons { font-size: 1rem; color: #f59e0b; } }
    .review-date { font-size: 0.8125rem; color: var(--gray); }

    .action-card { margin-bottom: 1.5rem; }

    .related-section { h3 { font-size: 1.125rem; margin-bottom: 1rem; } }
    .related-item { display: flex; gap: 0.75rem; margin-bottom: 1rem; align-items: center;
      img { width: 64px; height: 64px; object-fit: cover; border-radius: 8px; }
      a { font-weight: 600; color: var(--dark); display: block; &:hover { color: var(--primary); } }
      p { margin: 0; font-size: 0.8125rem; color: var(--gray); }
    }
  `]
})
export class DestinationDetailComponent implements OnInit {
  destination: any = null;
  relatedDestinations: any[] = [];
  reviews: any[] = [];
  isFavorite = false;
  loadingError = false;
  newReview: any = { rating: 0, comment: '' };
  reviewSuccess = false;

  constructor(private api: ApiService, public auth: AuthService, private route: ActivatedRoute) {}

  ngOnInit() {
    const slug = this.route.snapshot.paramMap.get('slug') || this.route.snapshot.paramMap.get('id');
    this.loadDestination(slug!);
  }

  loadDestination(slug: string) {
    this.api.getDestination(slug).subscribe({
      next: (data) => {
        this.destination = data;
        this.relatedDestinations = data.relatedTo?.map((r: any) => r.from).filter(Boolean) || [];
        this.reviews = data.reviews || [];
        if (this.auth.isLoggedIn()) this.checkFavorite();
      },
      error: () => { this.loadingError = true; }
    });
  }

  getHighlights(): string[] {
    if (!this.destination?.highlights) return [];
    try { return JSON.parse(this.destination.highlights); } catch { return []; }
  }

  toggleFavorite() {
    if (!this.auth.isLoggedIn()) return;
    if (this.isFavorite) {
      this.api.removeFavorite(this.destination.id).subscribe(() => { this.isFavorite = false; });
    } else {
      this.api.addFavorite(this.destination.id).subscribe(() => { this.isFavorite = true; });
    }
  }

  checkFavorite() {
    this.api.checkFavorite(this.destination.id).subscribe((res) => { this.isFavorite = res.isFavorite; });
  }

  submitReview() {
    if (!this.newReview.rating || !this.newReview.comment.trim()) return;
    this.api.createReview({
      destinationId: this.destination.id,
      rating: this.newReview.rating,
      comment: this.newReview.comment,
    }).subscribe({
      next: (res) => {
        this.reviews.unshift(res);
        this.newReview = { rating: 0, comment: '' };
        this.reviewSuccess = true;
        setTimeout(() => this.reviewSuccess = false, 3000);
      }
    });
  }
}
